return [{ json: row }];

const result = $('Evaluate Config Gateway').first()?.json ?? {};
const entry = result.write_plan?.[2];
if (!entry) return [];
const row = entry.row ?? { ...(entry.match ?? {}), ...(entry.patch ?? {}) };
return [{ json: row }];

const result = $('Evaluate Config Gateway').first()?.json ?? {};
const entry = result.write_plan?.[3];
if (!entry) return [];
const row = entry.row ?? { ...(entry.match ?? {}), ...(entry.patch ?? {}) };
